def is_Diff(n):
    # Convert number to string to apply the divisibility rule for 11
    s = str(n)
    # Calculate the alternating sum of digits
    total = 0
    for i in range(len(s)):
        if i % 2 == 0:
            total += int(s[i])
        else:
            total -= int(s[i])
    return total % 11 == 0
```

