def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Generate the next palindrome based on the length
    if all(c == '9' for c in numstr):
        return 10**length + 1

    # Helper function to create a palindrome from a seed
    def create_palindrome(seed, even_length):
        if even_length:
            return seed + seed[::-1]
        else:
            return seed + seed[:-1][::-1]

    # Start with the number as a seed
    seed = numstr[: (length + 1) // 2]
    seed = int(seed)

    while True:
        seed += 1
        pal = create_palindrome(str(seed), length % 2 == 0)
        if int(pal) > num:
            return int(pal)
```

