def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Handle the case where the number is all 9s (e.g., 99 -> 101)
    if all(c == '9' for c in numstr):
        return 10**length + 1

    # Generate the next palindrome based on the length
    half = numstr[:(length + 1) // 2]
    next_half = str(int(half) + 1)

    # Case 1: Palindrome with same length
    if length % 2 == 0:
        candidate = int(half + half[::-1])
    else:
        candidate = int(half + half[-2::-1])

    if candidate > num:
        return candidate

    # Case 2: Increment the half and mirror
    if len(next_half) > len(half):
        return int(next_half + next_half[::-1][1:]) if length % 2 == 0 else int(next_half + next_half[::-1])
    else:
        return int(next_half + next_half[::-1][1:]) if length % 2 == 0 else int(next_half + next_half[::-1])
```

