def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Helper function to create the next palindrome
    def create_palindrome(s, is_odd):
        if is_odd:
            return s + s[:-1][::-1]
        else:
            return s + s[::-1]

    # Case 1: All 9s, e.g., 999 -> next is 1001
    if all(c == '9' for c in numstr):
        return 10**length + 1

    # Case 2: Generate the next palindrome
    half = numstr[:(length + 1) // 2]
    next_half = str(int(half) + 1)

    if len(next_half) > len(half):
        return 10**length + 1

    if length % 2 == 0:
        candidate = create_palindrome(next_half, False)
    else:
        candidate = create_palindrome(next_half, True)

    if candidate > num:
        return candidate

    # If candidate is not greater, increment half and try again
    while True:
        half = str(int(half) + 1)
        if len(half) > len(numstr) // 2 + (length % 2):
            return 10**length + 1
        if length % 2 == 0:
            candidate = create_palindrome(half, False)
        else:
            candidate = create_palindrome(half, True)
        if candidate > num:
            return candidate
