def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = 1  # Any number can be the first element in a sequence of length 1

    for length in range(2, n + 1):
        for current in range(1, m + 1):
            # For each possible previous number that is <= current // 2
            # We sum the number of sequences of length (length - 1) ending with that previous number
            dp[current][length] = sum(dp[prev][length - 1] for prev in range(1, current // 2 + 1))

    return dp[m][n]
```

