def count_no_of_ways(n, k): 
    if n == 0:
        return 0
    if n == 1:
        return k
    dp = [0] * (n + 1)
    dp[1] = k
    dp[2] = k * (k - 1) + k  # k ways for same color, k*(k-1) for different
    for i in range(3, n + 1):
        dp[i] = (k - 1) * (dp[i - 1] + dp[i - 2]) % 1000000007
    return dp[n]
