def max_product(arr):
    n = len(arr)
    dp = [1] * n  # dp[i] will store the maximum product for increasing subsequence ending at i

    for i in range(n):
        dp[i] = arr[i]  # Initialize with the number itself
        for j in range(i):
            if arr[j] < arr[i]:  # Check for increasing subsequence
                dp[i] = max(dp[i], dp[j] * arr[i])

    return max(dp)
```

