    max_prod = [0] * n
    max_prod[0] = arr[0]

    for i in range(1, n):
        max_prod[i] = arr[i]
        j = i - 1
        while j >= 0 and arr[j] < arr[i]:
            max_prod[i] = max(max_prod[i], max_prod[j] * arr[i])
            j -= 1

    return max(max_prod)
